import{_ as o,o as e,c,ag as r}from"./chunks/framework.KxDd3USm.js";const b=JSON.parse('{"title":"09.9 精华题与专项题","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/91-精华题与专项题.md","filePath":"09-计算机系统基础/91-精华题与专项题.md"}'),d={name:"09-计算机系统基础/91-精华题与专项题.md"};function s(t,p,n,a,g,C){return e(),c("div",null,[...p[0]||(p[0]=[r('<h1 id="_09-9-精华题与专项题" tabindex="-1">09.9 精华题与专项题 <a class="header-anchor" href="#_09-9-精华题与专项题" aria-label="Permalink to &quot;09.9 精华题与专项题&quot;">​</a></h1><p><strong>1.</strong> 8 位补码可表示的最小整数及其编码分别是（ ）。</p><p>A. −127，<code>11111111</code><br> B. −127，<code>10000001</code><br> C. −128，<code>10000000</code><br> D. −128，<code>11111111</code></p><p><strong>2.</strong> 若先查 Cache 需 6 ns，未命中后追加访问主存需 94 ns，Cache 命中率为 98%，平均访问时间为（ ）。</p><p>A. 6.00 ns<br> B. 7.88 ns<br> C. 8.00 ns<br> D. 98.12 ns</p><p><strong>3.</strong> 用 <code>8K×4 bit</code> 芯片组成 <code>32K×16 bit</code> 存储器，至少需要（ ）片。</p><p>A. 4<br> B. 8<br> C. 16<br> D. 32</p><p><strong>4.</strong> 某磁盘转速为 12000 RPM，每磁道 100 个扇区。忽略寻道时间，平均旋转等待加读取 2 个连续扇区的时间约为（ ）。</p><p>A. 0.10 ms<br> B. 2.50 ms<br> C. 2.60 ms<br> D. 5.10 ms</p><p><strong>5.</strong> 一个系统由三个可靠度为 0.9 的模块串联。若把中间模块改为两个相同模块并联，其余不变，改造后总可靠度为（ ）。</p><p>A. 0.729<br> B. 0.8019<br> C. 0.891<br> D. 0.9801</p><p><strong>6.</strong> 关于校验码，下列说法正确的是（ ）。</p><p>A. 奇偶校验能发现所有两位错误<br> B. CRC 通过普通带借位除法求余数<br> C. 海明码利用多个奇偶校验组定位错误位<br> D. 接收方 CRC 余数为 0 就能证明数据绝对没有错误</p><p><strong>7.</strong> 某流水线有 4 段，每段统一为 5 ns，连续执行 20 个任务。流水时间和最大吞吐率分别是（ ）。</p><p>A. 100 ns，2×10^8 个/秒<br> B. 115 ns，2×10^8 个/秒<br> C. 115 ns，5×10^9 个/秒<br> D. 400 ns，5×10^7 个/秒</p><hr><h2 id="扩充专项题-本轮新增" tabindex="-1">扩充专项题（本轮新增） <a class="header-anchor" href="#扩充专项题-本轮新增" aria-label="Permalink to &quot;扩充专项题（本轮新增）&quot;">​</a></h2><p><strong>1.</strong> 4 位补码表示的 −3 为 <code>1101</code>，对应的移码是（ ）。</p><p>A. <code>0010</code></p><p>B. <code>0101</code></p><p>C. <code>1010</code></p><p>D. <code>1101</code></p><p><strong>2.</strong> 二进制浮点数 <code>0.1100×2^3 + 0.1100×2^3</code> 相加后，规格化结果是（ ）。</p><p>A. <code>0.1100×2^3</code></p><p>B. <code>0.1100×2^4</code></p><p>C. <code>0.0110×2^4</code></p><p>D. <code>1.1000×2^4</code></p><p><strong>3.</strong> 地址范围为 <code>B3000H～DABFFH</code>，按字节编址，其容量是（ ）。</p><p>A. 158 KiB</p><p>B. 159 KiB</p><p>C. 160 KiB</p><p>D. 162816 KiB</p><p><strong>4.</strong> 直接映射 Cache 的主存地址通常划分为（ ）。</p><p>A. 标记、块内偏移</p><p>B. 标记、组号、块内偏移</p><p>C. 标记、行号、块内偏移</p><p>D. 行号、组号、替换算法</p><p><strong>5.</strong> 某磁盘转速为 6000 RPM，平均寻道时间 5 ms，每道 100 个扇区。现读取 4 个随机散落的扇区，假定每个扇区都重新寻道并经历平均旋转等待，则总时间约为（ ）。</p><p>A. 10.1 ms</p><p>B. 10.4 ms</p><p>C. 25.4 ms</p><p>D. 40.4 ms</p><p><strong>6.</strong> 采用相对寻址，若 <code>(PC)=1000</code>，地址字段为 −20，则有效地址 EA 为（ ）。</p><p>A. −20</p><p>B. 980</p><p>C. 1000</p><p>D. 1020</p><p><strong>7.</strong> 关于 RISC、CISC 与流水线，下列说法正确的是（ ）。</p><p>A. 只有 RISC 才能使用流水线，CISC 绝对不能</p><p>B. 只有 CISC 才能使用流水线</p><p>C. 两者都可采用流水线，但 RISC 的规整指令通常更容易高效流水化</p><p>D. 是否适合流水线只取决于寄存器数量</p><p><strong>8.</strong> 500 台同型设备各观察 2000 h，共发生 5 次故障。估计恒定失效率 λ 为（ ）。</p><p>A. <code>5×10^−3/h</code></p><p>B. <code>5×10^−5/h</code></p><p>C. <code>5×10^−6/h</code></p><p>D. <code>2×10^5/h</code></p><p><strong>9.</strong> 某设备修复时间服从指数分布，MTTR=2 h。其在 4 h 内修复的概率约为（ ）。</p><p>A. 0.1353</p><p>B. 0.5000</p><p>C. 0.6321</p><p>D. 0.8647</p><p><strong>10.</strong> 某编码的最小码距为 5，它最多能保证检测 e 位错误、纠正 t 位错误。正确的是（ ）。</p><p>A. e=4，t=2</p><p>B. e=5，t=2</p><p>C. e=4，t=3</p><p>D. e=2，t=4</p><p><strong>11.</strong> 信息位 <code>1101</code>，CRC 除数为 <code>1011</code>，则应补的 0 的个数和最终余数分别是（ ）。</p><p>A. 2 个，<code>01</code></p><p>B. 3 个，<code>001</code></p><p>C. 3 个，<code>101</code></p><p>D. 4 个，<code>0001</code></p><p><strong>12.</strong> 4 位数据 <code>1011</code> 按本课规则生成偶校验海明码 <code>0110011</code>。若收到 <code>0110001</code>，综合征 <code>s4s2s1</code> 和错误位置分别是（ ）。</p><p>A. <code>011</code>，第 3 位</p><p>B. <code>101</code>，第 5 位</p><p>C. <code>110</code>，第 6 位</p><p>D. <code>111</code>，第 7 位</p><hr>',78)])])}const B=o(d,[["render",s]]);export{b as __pageData,B as default};
